INSERT INTO `awards_catalog` (`id`, `name`, `img_file`, `category`, `description`, `sort_order`) VALUES
(1, 'Герой України (посмертно)', 'hero_ukraine.png', 'hero', 'За здійснення видатного подвигу або визначний особистий внесок у захист суверенітету та територіальної цілісності України', 1),
(2, 'Орден Свободи', 'order_freedom.png', 'order', 'За особливі заслуги перед Україною у захисті державного суверенітету, зміцненні демократії, прав і свобод людини', 10),
(3, 'Орден Героїв Небесної Сотні', 'order_heavenly_hundred.png', 'order', 'За особисту мужність і героїзм, виявлені під час захисту демократичних цінностей та прав людини', 11),
(4, 'Орден «За мужність» I ступеня', 'order_courage_1.png', 'order', 'За особисту мужність і героїзм, виявлені в бойових діях при захисті державного суверенітету та територіальної цілісності України', 20),
(5, 'Орден «За мужність» II ступеня', 'order_courage_2.png', 'order', 'За мужність і відвагу в бойових діях, самовіддане виконання військового обов\'язку', 21),
(6, 'Орден «За мужність» III ступеня', 'order_courage_3.png', 'order', 'За особисту мужність і стійкість, виявлені при виконанні військового та громадянського обов\'язку', 22),
(7, 'Орден Богдана Хмельницького I ступеня', 'order_khmelnytsky_1.png', 'order', 'За видатні заслуги у зміцненні обороноздатності держави, вагомий внесок у розвиток Збройних Сил України', 30),
(8, 'Орден Богдана Хмельницького II ступеня', 'order_khmelnytsky_2.png', 'order', 'За значний внесок у зміцнення обороноздатності держави та розвиток Збройних Сил України', 31),
(9, 'Орден Богдана Хмельницького III ступеня', 'order_khmelnytsky_3.png', 'order', 'За мужність і відвагу при виконанні бойових завдань, сумлінну військову службу', 32),
(10, 'Орден Данила Галицького', 'order_galician.png', 'order', 'За визначні заслуги у захисті державного суверенітету, зміцненні обороноздатності та безпеки України', 40),
(11, 'Орден «За заслуги» I ступеня', 'order_merit_1.png', 'order', 'За видатні заслуги перед Україною у сфері державного будівництва, зміцнення обороноздатності та безпеки', 50),
(12, 'Орден «За заслуги» II ступеня', 'order_merit_2.png', 'order', 'За значний внесок у розбудову України, зміцнення її обороноздатності та безпеки', 51),
(13, 'Орден «За заслуги» III ступеня', 'order_merit_3.png', 'order', 'За заслуги перед державою, вагомий внесок у розвиток суспільства', 52),
(14, 'Орден князя Ярослава Мудрого I ступеня', 'order_yaroslav_1.png', 'order', 'За визначний особистий внесок у державне будівництво та зміцнення міжнародного авторитету України', 60),
(15, 'Орден князя Ярослава Мудрого II ступеня', 'order_yaroslav_2.png', 'order', 'За значний внесок у зміцнення державності, розвиток суспільства та міжнародного співробітництва', 61),
(16, 'Орден князя Ярослава Мудрого III ступеня', 'order_yaroslav_3.png', 'order', 'За заслуги у розвитку науки, освіти, культури та зміцненні держави', 62),
(17, 'Орден князя Ярослава Мудрого IV ступеня', 'order_yaroslav_4.png', 'order', 'За заслуги перед Україною у сфері державотворення та суспільного розвитку', 63),
(18, 'Орден князя Ярослава Мудрого V ступеня', 'order_yaroslav_5.png', 'order', 'За багаторічну сумлінну службу та вагомий особистий внесок у розвиток держави', 64),
(19, 'Хрест бойових заслуг', 'cross_combat.png', 'cross', 'За особисту мужність і умілі дії в боях при захисті державного суверенітету та територіальної цілісності України', 100),
(20, 'Хрест хоробрих', 'cross_brave.png', 'cross', 'За особисту мужність і відвагу, виявлені при виконанні бойових завдань', 101),
(21, 'Медаль «Захиснику Вітчизни»', 'medal_defender.png', 'medal', 'За захист державного суверенітету та територіальної цілісності України, зразкове виконання військового обов\'язку', 200),
(22, 'Медаль «За поранення»', 'medal_wound.png', 'medal', 'Вручається військовослужбовцям, які отримали поранення (контузію, травму, каліцтво) під час виконання бойових завдань', 201),
(23, 'Медаль «За військову службу Україні»', 'medal_service.png', 'medal', 'За зразкове виконання військового обов\'язку, бездоганну службу та вагомий внесок у зміцнення обороноздатності держави', 210),
(24, 'Медаль «За бездоганну службу» I ступеня', 'medal_flawless.png', 'medal', 'За бездоганну довготривалу військову службу та зразкове виконання службових обов\'язків', 220),
(25, 'Медаль «За бездоганну службу» II ступеня', 'medal_flawless_2.png', 'medal', 'За бездоганну довготривалу військову службу та зразкове виконання службових обов\'язків', 221),
(26, 'Медаль «За бездоганну службу» III ступеня', 'medal_flawless_3.png', 'medal', 'За бездоганну довготривалу військову службу та зразкове виконання службових обов\'язків', 222),
(27, 'Медаль «За врятоване життя»', 'medal_lifesaving.png', 'medal', 'За особисту мужність і самопожертву, виявлені при рятуванні людей від загибелі', 230),
(28, 'Нагрудний знак «За воїнську доблесть»', 'badge_valor.png', 'badge', 'За мужність, ініціативність та самовіддане виконання обов\'язку у захисті державного суверенітету', 300),
(29, 'Відзнака «За вірність присязі»', 'badge_oath.png', 'badge', 'За вірне служіння Батьківщині та неухильне виконання Військової присяги', 301),
(30, 'Відзнака «За заслуги перед ЗСУ»', 'badge_zsu.png', 'badge', 'За заслуги перед Збройними Силами України у зміцненні обороноздатності держави', 302),
(31, 'Відзнака Президента «За участь в АТО»', 'badge_ato.png', 'badge', 'Відзнака Президента України учасникам антитерористичної операції', 303),
(32, 'Орден Михайла Грушевського', 'order_hrushevsky.png', 'order', 'За видатний особистий внесок у відродження та розбудову Української держави', 70),
(33, 'Медаль «За зразкову службу» I ступеня', 'medal_exemplary_1.png', 'medal', 'Відомча медаль МО України І ступеня', 240),
(34, 'Медаль «За зразкову службу» II ступеня', 'medal_exemplary_2.png', 'medal', 'Відомча медаль МО України ІІ ступеня', 241),
(35, 'Медаль «За зразкову службу» III ступеня', 'medal_exemplary_3.png', 'medal', 'Відомча медаль МО України ІІІ ступеня', 242),
(36, 'Медаль «Учасник бойових дій»', 'medal_combat_vet.png', 'medal', 'Вручається учасникам бойових дій на захист Батьківщини', 250),
(37, 'Медаль «За участь у миротворчій операції»', 'medal_peacekeeping.png', 'medal', 'За участь у міжнародних миротворчих операціях', 260),
(38, 'Медаль «За сприяння Збройним Силам України»', 'medal_support_zsu.png', 'medal', 'За вагомий внесок у зміцнення обороноздатності держави', 270),
(39, 'Нагрудний знак «Золотий хрест» ЗСУ', 'badge_golden_cross.png', 'badge', 'За видатні заслуги та мужність у захисті України', 310),
(40, 'Нагрудний знак «Срібний хрест» ЗСУ', 'badge_silver_cross.png', 'badge', 'За особисту мужність та відвагу', 311),
(41, 'Відзнака ГК ЗСУ «За особисту мужність»', 'badge_gk_courage.png', 'badge', 'Відзнака Головнокомандувача ЗСУ за особисту мужність', 312),
(42, 'Відзнака ГК ЗСУ «За вірну службу»', 'badge_gk_faithful.png', 'badge', 'Відзнака Головнокомандувача ЗСУ за вірну службу Батьківщині', 313),
(43, 'Хрест «За службу Батьківщині» I ступеня (НГУ)', 'ngu_cross_1.png', 'cross', 'Відомча відзнака НГУ І ступеня', 110),
(44, 'Хрест «За службу Батьківщині» II ступеня (НГУ)', 'ngu_cross_2.png', 'cross', 'Відомча відзнака НГУ ІІ ступеня', 111),
(45, 'Хрест «За службу Батьківщині» III ступеня (НГУ)', 'ngu_cross_3.png', 'cross', 'Відомча відзнака НГУ ІІІ ступеня', 112),
(46, 'Медаль «За доблесть» (НГУ)', 'ngu_medal_valor.png', 'medal', 'Відомча медаль НГУ за виявлену доблесть', 280),
(47, 'Медаль «За сприяння» (НГУ)', 'ngu_medal_support.png', 'medal', 'Відомча медаль НГУ за сприяння', 281),
(48, 'Медаль «За охорону державного кордону»', 'dpsu_medal_border.png', 'medal', 'Відомча медаль ДПСУ', 290),
(49, 'Хрест «За службу державному кордону»', 'dpsu_cross.png', 'cross', 'Відомча відзнака ДПСУ', 120),
(50, 'Медаль ДПСУ «За бездоганну службу» I ступеня', 'dpsu_medal_flawless_1.png', 'medal', 'Відомча медаль ДПСУ І ступеня', 291),
(51, 'Медаль ДПСУ «За бездоганну службу» II ступеня', 'dpsu_medal_flawless_2.png', 'medal', 'Відомча медаль ДПСУ ІІ ступеня', 292),
(52, 'Медаль СБУ «За доблесть» I ступеня', 'sbu_medal_valor_1.png', 'medal', 'Відомча медаль СБУ І ступеня', 295),
(53, 'Медаль СБУ «За доблесть» II ступеня', 'sbu_medal_valor_2.png', 'medal', 'Відомча медаль СБУ ІІ ступеня', 296),
(54, 'Медаль СБУ «За сприяння»', 'sbu_medal_support.png', 'medal', 'Відомча медаль СБУ', 297),
(55, 'Відзнака Президента «Іменна вогнепальна зброя»', 'badge_named_weapon.png', 'badge', 'За особливі заслуги перед державою', 320),
(56, 'Грамота Верховної Ради України', 'vr_diploma.png', 'badge', 'Почесна грамота ВРУ', 330),
(57, 'Медаль МВС «За доблесну службу»', 'mvs_medal_valor.png', 'medal', 'Відомча медаль МВС', 298),
(58, 'Медаль Національної поліції «За службу»', 'police_medal_service.png', 'medal', 'Відомча медаль Нацполіції', 299),
(59, 'Медаль ДСНС «За доблесть»', 'dsns_medal_valor.png', 'medal', 'Відомча медаль ДСНС', 285);
