INSERT INTO `chat_bot_phrases` (`id`, `phrase`, `category`, `is_active`) VALUES
(1, 'Дуже важливий проєкт, дякую що зберігаєте пам\'ять про героїв 🙏', 'positive', 0),
(2, 'Нещодавно знайшла тут запис про свого дядька. Дякую вам.', 'personal', 1),
(3, 'Чи можна додати фільтр за областю?', 'suggestion', 0),
(4, 'Зіркова карта виглядає дуже красиво ✨', 'positive', 1),
(5, 'Показав друзям — всі були вражені. Чудова робота!', 'positive', 1),
(6, 'Я б додав можливість завантажити фото з телефону простіше.', 'suggestion', 0),
(7, 'Дякую за цей проєкт. Моя родина шукала інформацію тут.', 'personal', 1),
(8, 'Чи планується мобільний додаток?', 'suggestion', 0),
(9, 'Яскраві зірки на карті — дуже символічно 💫', 'positive', 1),
(10, 'Знайшов тут свого однокласника. Вічна пам\'ять.', 'personal', 1),
(12, 'Може додати можливість поділитись записом у Telegram?', 'suggestion', 1),
(13, 'Ромашки б гарно виглядали як символ на карті 🌼', 'suggestion', 1),
(14, 'Дуже зворушливий проєкт. Слава Україні!', 'positive', 1),
(15, 'Чи є спосіб повідомити якщо знайшов помилку в записі?', 'suggestion', 1),
(16, 'Карта завантажується миттєво, молодці розробники!', 'positive', 1),
(17, 'Додав свого брата. Дякую що є такий сайт.', 'personal', 0),
(18, 'Пам\'ять про героїв живе завдяки таким проєктам ❤️', 'positive', 1),
(19, 'Чи можна переглянути записи за роком загибелі?', 'suggestion', 0),
(20, 'Нехай кожна зірка світить вічно 🌟', 'positive', 1);
