(753, 'en', 'modal', 'modal.rules.general1', 'The site is intended solely for honoring the memory of fallen defenders of Ukraine.', '2026-07-14 15:46:05'),
(754, 'en', 'modal', 'modal.rules.general2', 'It is forbidden to post information that offends the honor and dignity of the fallen or their families.', '2026-07-14 15:46:05'),
