(756, 'en', 'modal', 'modal.rules.general4', 'The administration reserves the right to delete records that violate the rules.', '2026-07-14 15:46:05'),
(757, 'en', 'modal', 'modal.rules.general5', 'All records go through moderation before publication.', '2026-07-14 15:46:05'),
(758, 'en', 'modal', 'modal.rules.general_title', 'General rules', '2026-07-14 15:46:05'),
(759, 'en', 'modal', 'modal.rules.intro', '\"Memory Star\" is an open memorial for fallen defenders of Ukraine. It was created with respect for the memory of every warrior.', '2026-07-14 23:11:26'),
