(1038, 'en', 'doc', 'doc.last_revision', 'Last revision:', '2026-07-15 01:08:29'),
(1039, 'en', 'doc', 'doc.memorial_portal', 'Memorial web portal', '2026-07-15 01:08:29'),
(1040, 'en', 'doc', 'doc.min_estimate', 'Minimum estimate (market)', '2026-07-15 01:08:29'),
(1041, 'en', 'doc', 'doc.min_project_cost', 'Minimum project cost', '2026-07-15 01:08:29'),
